7.4.1 P1口控制8只LED每0.5s闪亮一次
void timer0() interrupt 1 //T0中断程序
{
TH0=0xee; //重新赋初值
TL0=0x00;
i--; //循环次数减1
if(i<=0)
{
P1=~P1; //P1口按位取反
i=100; //重置循环次数
}
}

