7.4.4 利用T1控制发出1kHz的音频信号
void main(void) {
EA=1; //开总中断.
ET1=1; //允许定时器T1中断 .
TMOD=0x10; //TMOD=0001 000B，使用T1的方式1定时
TH1=f1(i); //给T1高8位赋初值.
TL1=f2(i); //给T1低8位赋初值.
TR1=1; //启动T1
while(1) { //循环等待
i=500; 
while(j<2000);
j=0;
i=1000; 
while(j<2000);
j=0; }
}
