7.4.4 利用T1控制发出1kHz的音频信号
//定时器T1中断函数
void T1(void) interrupt 3 using 0
{
TR1= 0; //关闭T1
sound=~sound; //P1.7输出求反
TH1=f1(i); //T1的高8位重新赋初值.
TL1=f2(i); //T1的低8位重新赋初值.
j++;
TR1=1; //启动定时器T1
}
