7.4.6 测量脉冲宽度—门控位GATEx的应用
//数码管显示函数
void display(uint a,uint b,uint c,uint d,uint e,uint f) {
P2=0xfe; 
P0=table[f];
delay(2);
P2=0xfd;
P0=table[e];
delay(2);
P2=0xfb;
P0=table[d];
delay(2);
P2=0xf7;
P0=table[c];
delay(2);
P2=0xef;
P0=table[b];
delay(2);
P2=0xdf;
P0=table[a];
delay(2);
}

7.4.6 测量脉冲宽度—门控位GATEx的应用
void read_count() { //读取计数寄存器的内容
do {
count_high=TH1; //读高字节
count_low=TL1; //读低字节
}while (count_high!=TH1);
num=count_high*256+count_low; 
/*可将两字节的机器周期数进行显示处理*/
}

7.4.6 测量脉冲宽度—门控位GATEx的应用
void main( ) {
while(1) {
flag=0;
TMOD=0x90; //设置定时器T1为方式1定时
TH1=0; //向定时器T1写入计数初值
TL1=0;
while(P3_3==1); //等待INT1*变低
TR1=1; //如果INT1*为低，启动
//T1（未真正开始计数）
while(P3_3==0); //等待INT1* 变高，变高
//后T1真正开始计数

7.4.6 测量脉冲宽度—门控位GATEx的应用
while(P3_3==1); //等待INT1*变低，变低后T1停止计数
TR1=0;
read_count(); //读计数寄存器内容的函数
shiwan=num/100000;
wan=num%100000/10000;
qian=num%10000/1000;
bai=num%1000/100;
shi=num%100/10;
ge=num%10;
while(flag!=100) { //减小刷新频率
