}
void main() {
init1602(); //LCD初始化
clock_init(); //时钟初始化
TMOD=0x01; //设置定时器T0为方式1定时
EA=1; // 总中断开
ET0=1; // 允许T0中断
TH0=(65536-46483)/256; //给T0装初值

7.4.7 LCD时钟的设计
TL0=(65536-46483)%256;
TR0=1;
int_time=0; //中断次数、秒、分、时单元清0
second=55;
minute=59;
hour=23;
while(1) {
clock_write(second ,minute, hour);
}
}

7.4.7 LCD时钟的设计
//T0中断服务子程序
void T0_interserve(void) interrupt 1 using 1 {
int_time++; //中断次数加1
if(int_time==20) //若中断次数计满20次
{ 
int_time=0; //中断次数变量清0
second++; //秒计数变量加 1
}
if(second==60) { //若计满60s
second=0; //秒计数变量清0
minute ++; //分计数变量加 1
}

7.4.7 LCD时钟的设计
if(minute==60) { //若计满60分
minute=0; //分计数变量清0
hour ++; //小时计数变量加1
}
if(hour==24) { 
hour=0; //小时计数计满24，将小时计数变量清0
}
TH0=(65536-46083)/256; //定时器T0重新赋值
TL0=(65536-46083)%256;
}
执行上述程序仿真运行，就会在LCD上显示实时时间。

7.5.2 T2的16位自动重装载方式
void main(void)
{
CP_RL2=0; EXEN2=0; //设置T2为16位自动重装裁定时器
//工作方式
P1_0=1; //P1_0引脚LED熄灭
TH2=RCAP2H=0xDC; //给T2赋预装载初值，溢出时间
//为1/16秒
ET2=1; //T2中断允许
EA=1; //总中断允许
TR2=1; //启动T2 
while(1); //循环等待T2的1/16秒的溢出中断
}
